define(["jquery"],function($){function getViolationHtml(){return $.trim($("#proctoringpolicy_focus-message").html()||"")}function isExamActive(ctx){return!!(ctx&&ctx.api&&typeof ctx.api.isExamActive==="function"&&ctx.api.isExamActive())}function showViolationMessage(ctx){let html=getViolationHtml();if(!html||!isExamActive(ctx)){return}if(ctx.api&&typeof ctx.api.showViolationMessage==="function"){ctx.api.showViolationMessage("focus",html)}}function init(ctx,cfg){if(!ctx||!cfg){return}let limit=parseInt(cfg.limit||0,10);if(isNaN(limit)||limit<0){limit=3}let count=0;let namespace=".kopere_proctoring_focus";function registerEvent(kind,detail){if(!isExamActive(ctx)){return}count++;showViolationMessage(ctx);if(typeof ctx.sendEvent==="function"){ctx.sendEvent("focus_"+kind,{count:count,detail:detail||""})}if(limit>0&&count>limit&&typeof ctx.lock==="function"){ctx.lock("focus",getViolationHtml())}}$(window).on("blur"+namespace,function(){registerEvent("blur","window")});$(document).on("visibilitychange"+namespace,function(){if(document.hidden){registerEvent("visibilitychange","hidden")}})}return{init:init}});